// Print tree in level order array format
function printTree(root) {
    if (root === null) {
        console.log("[]");
        return;
    }

    let ans = [];
    let q = [];
    q.push(root);

    while (q.length > 0) {
        let curr = q.shift();

        if (curr !== null) {
            ans.push(curr.data.toString());
            q.push(curr.left);
            q.push(curr.right);
        } else {
